    valid_tokens = {'magic_wand', 'paper_lantern', 'time_machine', 'space_traveler', 'heat_pump', 'lightning_bolt', 'flying_pig', 'time_mirror'}
    test_cases = [('magic_wand', True), ('paper_lantern', True), ('flying_pig', False), ('time_mirror', True), ('heat_pump', False), ('lightning_bolt', False)]
    for token, expected in test_cases:
        result = validate_token(token, valid_tokens)
        assert result == expected, f'validate_token({token}, {valid_tokens}) expected {expected} but got {result}'
    print('All test cases passed.')
